grid = [list(map(int, s)) for s in rows]
centers=[]
for r,row in enumerate(grid):
  for c,v in enumerate(row):
    if v not in (0,3): centers.append((r,c,v))
print(centers)
vert={c:v for r,c,v in centers}; horiz={r:v for r,c,v in centers}
out=[]
for r in range(19):
  outrow=[]
  for c in range(19):
    val=grid[r][c]
    if val: outrow.append(val)
    elif c in vert: outrow.append(vert[c])
    elif r in horiz: outrow.append(horiz[r])
    else: outrow.append(0)
  out.append(outrow)
print('\n'.join(' '.join(map(str,x)) for x in out))

